-- Phase 3 connected intelligence core. Applied to production 2026-08-13.
alter table public.intelligence_events add column if not exists subject_entity_type text;
alter table public.intelligence_events add column if not exists store_id uuid;
alter table public.intelligence_events add column if not exists event_version integer not null default 1;
alter table public.intelligence_events add column if not exists dedupe_key text;
alter table public.intelligence_events add column if not exists processing_status text not null default 'ready';
alter table public.intelligence_events add column if not exists identity_confidence numeric;
alter table public.intelligence_events add column if not exists metadata jsonb not null default '{}'::jsonb;
create unique index if not exists ux_intelligence_events_dedupe on public.intelligence_events(organization_id,source_system,dedupe_key) where dedupe_key is not null;
create index if not exists idx_intelligence_events_org_time on public.intelligence_events(organization_id,occurred_at desc);
create index if not exists idx_intelligence_events_type_time on public.intelligence_events(event_type,occurred_at desc);
create index if not exists idx_intelligence_events_store_time on public.intelligence_events(store_id,occurred_at desc) where store_id is not null;

insert into public.platform_canonical_entity_types(key,name,description,intelligence_entity_type,active,metadata) values
('interaction','Customer Interaction','Retail customer interaction / UP lifecycle','interaction',true,'{}'),
('learning','Learning Activity','Academy learning and assessment activity','learning',true,'{}'),
('field_visit','Field Visit','Field execution and store assessment activity','field_visit',true,'{}') on conflict(key) do nothing;
insert into public.platform_canonical_event_types(key,name,description,subject_entity_type,outcome_relevant,coaching_relevant,active,metadata) values
('traffic.observed','Traffic Observed','Store traffic/counter observation','store',false,true,true,'{}'),
('interaction.started','Interaction Started','Salesperson accepted or began a customer interaction','interaction',false,true,true,'{}'),
('interaction.completed','Interaction Completed','Customer interaction ended with a recorded outcome','interaction',true,true,true,'{}'),
('interaction.no_sale','Interaction No Sale','Customer interaction ended without a purchase','interaction',true,true,true,'{}'),
